    fn update_done_inductive(pre: Self, post: Self, rid: ReqId) { admit(); }

    pub proof fn consume_stub_inductive(
        pre: UnboundedLog::State<DT>,
        post: UnboundedLog::State<DT>,
        output: OutputOperation<DT>,
        rid: ReqId,
