#[inductive(update_place_ops_in_log_one)]
fn update_place_ops_in_log_one_inductive(pre: Self, post: Self, node_id: NodeId, rid: ReqId) {
    // Get the pre-state queue
    let pre_queued_ops = pre.combiner[node_id].get_Placed_queued_ops();
    let pre_local_updates = pre.local_updates;

    // Show that seq_unique(post.combiner[node_id].get_Placed_queued_ops()) holds
    assert(seq_unique(post.combiner[node_id].get_Placed_queued_ops())) by {
        assert(seq_unique(pre_queued_ops)) by {
            assert(pre.wf_combiner_for_node_id(node_id));
        }
        // Since rid is fresh (not in the old queue), appending it preserves uniqueness
    }

    // Show that QueueRidsUpdatePlaced holds for the new queue
    assert(QueueRidsUpdatePlaced(post.combiner[node_id].get_Placed_queued_ops(), post.local_updates, 0)) by {
        // For all indices j >= 0 (i.e., all indices in the queue)
        assert forall |j|
            0 <= j < post.combiner[node_id].get_Placed_queued_ops().len() implies {
                &&& post.local_updates.contains_key(#[trigger] post.combiner[node_id].get_Placed_queued_ops()[j])
                &&& post.local_updates[post.combiner[node_id].get_Placed_queued_ops()[j]].is_Placed()
            } by {
            if j == post.combiner[node_id].get_Placed_queued_ops().len() - 1 {
                // Last element is the new rid
                assert(post.combiner[node_id].get_Placed_queued_ops()[j] == rid);
                assert(post.local_updates.contains_key(rid));
                assert(post.local_updates[rid].is_Placed());
            } else {
                // Earlier elements are unchanged
                assert(pre.local_updates.contains_key(pre_queued_ops[j]));
                assert(pre.local_updates[pre_queued_ops[j]].is_Placed());
                // The update state for existing elements is preserved
            }
        }
    }

    // Show that LogRangeMatchesQueue holds for the new state
    assert(LogRangeMatchesQueue(post.combiner[node_id].get_Placed_queued_ops(), post.log, 0, post.local_versions[node_id], post.tail, node_id, post.local_updates)) by {
        // Prove by induction on the log range
        // The new log entry at post.tail - 1 (which is pre.tail) has node_id
        // The new queue element at the end is rid
        // We need to show they match
    }

    // Show that other nodes' combiner states are unchanged
    assert forall |node_id2| #[trigger] post.combiner.contains_key(node_id2) implies post.wf_combiner_for_node_id(node_id2) by {
        if node_id2 == node_id {
            // Already proven above
        } else {
            assert(post.combiner[node_id2] == pre.combiner[node_id2]);
            assert(pre.wf_combiner_for_node_id(node_id2));
        }
    }

    // Show that inv_readonly_requests_wf is preserved (unchanged)
    assert forall |rid2| #[trigger] post.local_reads.contains_key(rid2) implies post.wf_readstate(post.local_reads[rid2]) by {
        assert(post.local_reads[rid2] == pre.local_reads[rid2]);
        assert(pre.wf_readstate(pre.local_reads[rid2]));
    }
    assert(post.inv_readonly_requests_wf());

    // Show that inv_local_updates is preserved
    assert forall |rid2| #[trigger] post.local_updates.contains_key(rid2) implies post.inv_local_updates_wf(post.local_updates[rid2]) by {
        if rid2 == rid {
            assert(post.local_updates[rid2].is_Placed());
            let idx = post.local_updates[rid2].get_Placed_idx();
            assert(post.log.contains_key(idx));
            assert(idx < post.tail);
        } else {
            assert(pre.local_updates.contains_key(rid2));
            assert(pre.inv_local_updates_wf(pre.local_updates[rid2]));
        }
    }
    assert(post.inv_local_updates());

    // Show that inv_read_results is preserved (unchanged)
    assert(post.inv_read_results());

    // Show that inv_update_results is preserved
    assert forall |rid2| #[trigger] post.local_updates.contains_key(rid2) implies post.update_results_match(post.local_updates[rid2]) by {
        if rid2 == rid {
            assert(post.local_updates[rid2].is_Placed());
            // For Placed state, update_results_match is always true
        } else {
            assert(pre.local_updates.contains_key(rid2));
            assert(pre.update_results_match(pre.local_updates[rid2]));
        }
    }
    assert(post.inv_update_results());
}

