    assert(pre_combiner_state.is_Placed());
    let pre_queued_ops = pre_combiner_state.get_Placed_queued_ops();
    let pre_update_state = pre.local_updates[rid];
    assert(pre_update_state.is_Init());
    let write_op = pre_update_state.get_Init_op();

    // In pre-state, the invariant holds
    assert(pre.wf_combiner_for_node_id(node_id));

    // Show that seq_unique(post.combiner[node_id].get_Placed_queued_ops()) holds
    assert(seq_unique(post.combiner[node_id].get_Placed_queued_ops())) by {
        assert(seq_unique(pre_queued_ops)) by {
            // From pre.wf_combiner_for_node_id
        }
        // Since rid was not in pre.local_updates (by transition condition),
        // and pre_queued_ops only contains rids that are in local_updates,
        // rid is not in pre_queued_ops. Appending a new element to a unique sequence preserves uniqueness.
    }

    // Show that QueueRidsUpdatePlaced holds for the new queue
    assert(QueueRidsUpdatePlaced(post.combiner[node_id].get_Placed_queued_ops(), post.local_updates, 0)) by {
        // For all indices j >= 0 (i.e., all indices in the queue)
        assert forall |j|
            0 <= j < post.combiner[node_id].get_Placed_queued_ops().len() implies {
                &&& post.local_updates.contains_key(#[trigger] post.combiner[node_id].get_Placed_queued_ops()[j])
                &&& post.local_updates[post.combiner[node_id].get_Placed_queued_ops()[j]].is_Placed()
            } by {
            if j == post.combiner[node_id].get_Placed_queued_ops().len() - 1 {
                // Last element is the new rid
                assert(post.combiner[node_id].get_Placed_queued_ops()[j] == rid);
                assert(post.local_updates.contains_key(rid));
                assert(post.local_updates[rid].is_Placed());
            } else {
                // Earlier elements are unchanged
                assert(post.combiner[node_id].get_Placed_queued_ops()[j] == pre_queued_ops[j]);
                assert(pre.local_updates.contains_key(pre_queued_ops[j]));
                assert(pre.local_updates[pre_queued_ops[j]].is_Placed());
                // The update state for existing elements is preserved
            }
        }
    }

    // Show that LogRangeMatchesQueue holds for the new state
    // This is the key invariant: the log range matches the queue
    assert(LogRangeMatchesQueue(post.combiner[node_id].get_Placed_queued_ops(), post.log, 0, post.local_versions[node_id], post.tail, node_id, post.local_updates)) by {
